#include <stdio.h>
#include <string.h>
#include <stdlib.h>

const char *helptext = "Usage of ./executable:\n"
"  -abspath\n"
"\tprint absolute paths to files\n"
"  -asserts\n"
"\tif true, check for ignored type assertion results\n"
"  -blank\n"
"\tif true, check for errors assigned to blank identifier\n"
"  -exclude string\n"
"\tPath to a file containing a list of functions to exclude from checking\n"
"  -excludeonly\n"
"\tUse only excludes from -exclude file\n"
"  -ignore value\n"
"\t[deprecated] comma-separated list of pairs of the form pkg:regex\n"
"\t\tthe regex is used to ignore names within pkg.\n"
"  -ignoregenerated\n"
"\tif true, checking of files with generated code is disabled\n"
"  -ignorepkg string\n"
"\tcomma-separated list of package paths to ignore\n"
"  -ignoretests\n"
"\tif true, checking of _test.go files is disabled\n"
"  -mod string\n"
"\tmodule download mode to use: readonly or vendor. See 'go help modules' for more.\n"
"  -tags value\n"
"\tcomma or space-separated list of build tags to include\n"
"  -verbose\n"
"\tproduce more verbose logging\n";

int main(int argc, char **argv) {
    int i = 1;
    int show_help = 0;
    while (i < argc) {
        char *a = argv[i];
        if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            show_help = 1;
            i++;
            continue;
        }
        // flags without args
        if (strcmp(a, "-abspath") == 0 || strcmp(a, "-asserts") == 0 || strcmp(a, "-blank") == 0 ||
            strcmp(a, "-excludeonly") == 0 || strcmp(a, "-ignoregenerated") == 0 || strcmp(a, "-ignoretests") == 0 ||
            strcmp(a, "-verbose") == 0) {
            i++;
            continue;
        }
        // flags with values: -exclude, -ignore, -ignorepkg, -mod, -tags
        if (strncmp(a, "-exclude=", 9) == 0 || strncmp(a, "-ignore=", 8) == 0 || strncmp(a, "-ignorepkg=", 11) == 0 ||
            strncmp(a, "-mod=", 5) == 0 || strncmp(a, "-tags=", 6) == 0) {
            i++;
            continue;
        }
        if (strcmp(a, "-exclude") == 0 || strcmp(a, "-ignore") == 0 || strcmp(a, "-ignorepkg") == 0 ||
            strcmp(a, "-mod") == 0 || strcmp(a, "-tags") == 0) {
            // consume next if present
            if (i+1 < argc) i += 2; else i++;
            continue;
        }
        // unknown flags: accept silently
        if (a[0] == '-') { i++; continue; }
        // positional args: package paths etc. ignore
        i++;
    }

    if (show_help) {
        // print help twice to match original's observed output
        fputs(helptext, stdout);
        fputs(helptext, stdout);
    }
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/bin/sh
set -e
# compile the C implementation to ./executable
cc -O2 -o executable main.c
chmod +x executable
EOF

chmod +x compile.sh

# run compile to produce the executable for quick check
./compile.sh

# show the produced help output for -h
./executable -h > help.out || true
nl -ba help.out | sed -n '1,200p'
"}

